import java.util.*;

public class DiceRoom {
    static final int N = 3;

    // indices for faces: 0=front,1=back,2=left,3=right,4=top,5=bottom
    static int[][] rotateForward(int[][] faces) {
        int[] temp = faces[0];
        faces[0] = faces[4];
        faces[4] = faces[1];
        faces[1] = faces[5];
        faces[5] = temp;
        return faces;
    }

    static int[][] rotateBackward(int[][] faces) {
        int[] temp = faces[0];
        faces[0] = faces[5];
        faces[5] = faces[1];
        faces[1] = faces[4];
        faces[4] = temp;
        return faces;
    }

    static int[][] rotateLeft(int[][] faces) {
        int[] temp = faces[0];
        faces[0] = faces[2];
        faces[2] = faces[1];
        faces[1] = faces[3];
        faces[3] = temp;
        return faces;
    }

    static int[][] rotateRight(int[][] faces) {
        int[] temp = faces[0];
        faces[0] = faces[3];
        faces[3] = faces[1];
        faces[1] = faces[2];
        faces[2] = temp;
        return faces;
    }

    static boolean checkPassage(int[][] faces) {
        // front face: lower row indices (6,7,8) in flat representation
        // back face: lower row indices (6,7,8) as well
        for (int f = 0; f <= 1; f++) {
            for (int i = 6; i <= 8; i++) {
                if (faces[f][i] == 1) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] faces = new int[6][9];
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 9; j++) {
                faces[i][j] = sc.nextInt();
            }
        }

        // BFS to find minimum rotations
        Queue<int[][]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.add(faces);
        visited.add(Arrays.deepToString(faces));

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int s = 0; s < size; s++) {
                int[][] cur = queue.poll();
                if (checkPassage(cur)) {
                    System.out.println(steps);
                    return;
                }
                int[][] next;
                // rotate forward
                next = deepCopy(cur);
                rotateForward(next);
                String key = Arrays.deepToString(next);
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.add(next);
                }
                // rotate backward
                next = deepCopy(cur);
                rotateBackward(next);
                key = Arrays.deepToString(next);
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.add(next);
                }
                // rotate left
                next = deepCopy(cur);
                rotateLeft(next);
                key = Arrays.deepToString(next);
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.add(next);
                }
                // rotate right
                next = deepCopy(cur);
                rotateRight(next);
                key = Arrays.deepToString(next);
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.add(next);
                }
            }
            steps++;
        }
        System.out.println(-1);
    }

    static int[][] deepCopy(int[][] original) {
        int[][] copy = new int[6][9];
        for (int i = 0; i < 6; i++) {
            copy[i] = original[i].clone();
        }
        return copy;
    }
