    static class State {
        int front, back, left, right, up, down, dist;
        State(int f, int b, int l, int r, int u, int d, int dist) {
            this.front = f; this.back = b; this.left = l; this.right = r; this.up = u; this.down = d;
            this.dist = dist;
        }
    }

    static boolean hasBottomHole(String[] face) {
        // lower three squares = row 2 in a 3x3 face
        for (int j = 0; j < 3; j++) {
            if (isHole(face[2].charAt(j))) return true;
        }
        return false;
    }

    static boolean isHole(char c) {
        // Treat any non-solid marker as a hole.
        // Commonly problems use '.' for hole and anything else for wall.
        return c == '.';
    }

    static int encode(int f, int b, int l, int r, int u, int d) {
        return (((((f * 6 + b) * 6 + l) * 6 + r) * 6 + u) * 6 + d);
    }

