        boolean[] good = new boolean[6];
        for (int i = 0; i < 6; i++) good[i] = hasBottomHole(faces[i]);

        Queue<State> q = new ArrayDeque<>();
        boolean[] vis = new boolean[6 * 6 * 6 * 6 * 6 * 6];

        // initial orientation: face ids
        // 0 front, 1 back, 2 left, 3 right, 4 up, 5 down
        State start = new State(0, 1, 2, 3, 4, 5, 0);
        q.add(start);
        vis[encode(0, 1, 2, 3, 4, 5)] = true;

        while (!q.isEmpty()) {
            State cur = q.poll();

