                System.out.println(cur.dist);
                return;
            }

            // Rotate north: front->down, up->front, back->up, down->back
            State[] nexts = new State[] {
                new State(cur.up, cur.down, cur.left, cur.right, cur.back, cur.front, cur.dist + 1),   // north
                new State(cur.down, cur.up, cur.left, cur.right, cur.front, cur.back, cur.dist + 1),   // south
                new State(cur.right, cur.left, cur.front, cur.back, cur.up, cur.down, cur.dist + 1),   // west
                new State(cur.left, cur.right, cur.back, cur.front, cur.up, cur.down, cur.dist + 1)    // east
