6 7 8
*/

static void rotate_face_cw(char a[9]) {
    char t[9];
    memcpy(t, a, 9);
    a[0] = t[6]; a[1] = t[3]; a[2] = t[0];
    a[3] = t[7]; a[4] = t[4]; a[5] = t[1];
    a[6] = t[8]; a[7] = t[5]; a[8] = t[2];
}

static void copy_state(State *dst, const State *src) {
    memcpy(dst, src, sizeof(State));
}

/* Rotate whole cube toward viewer around x-axis:
   Front -> Down -> Back -> Up -> Front
   Left/Right spin in place
*/
static void rot_x(State *s) {
    State t;
    copy_state(&t, s);

    memcpy(s->f[0], t.f[4], 9); // U -> F
    memcpy(s->f[5], t.f[0], 9); // F -> D
    memcpy(s->f[1], t.f[5], 9); // D -> B
    memcpy(s->f[4], t.f[1], 9); // B -> U

    memcpy(s->f[2], t.f[2], 9);
    memcpy(s->f[3], t.f[3], 9);

    rotate_face_cw(s->f[2]);           // L
    rotate_face_cw(s->f[3]);           // R
    rotate_face_cw(s->f[3]);
    rotate_face_cw(s->f[3]);           // R ccw
}

/* Rotate whole cube around vertical axis:
   Left -> Front -> Right -> Back -> Left
   Up/Down spin in place
*/
static void rot_y(State *s) {
    State t;
    copy_state(&t, s);

    memcpy(s->f[0], t.f[2], 9); // L -> F
    memcpy(s->f[3], t.f[0], 9); // F -> R
    memcpy(s->f[1], t.f[3], 9); // R -> B
    memcpy(s->f[2], t.f[1], 9); // B -> L

    memcpy(s->f[4], t.f[4], 9);
    memcpy(s->f[5], t.f[5], 9);

    rotate_face_cw(s->f[4]);           // U cw
    rotate_face_cw(s->f[5]);           // D ccw
    rotate_face_cw(s->f[5]);
    rotate_face_cw(s->f[5]);
}

static int can_pass(const State *s) {
    /* lower three squares on front and back faces */
    for (int i = 6; i <= 8; i++) {
        if (s->f[0][i] == '1' && s->f[1][i] == '1') return 1;
    }
    return 0;
}

static int same_state(const State *a, const State *b) {
    return memcmp(a, b, sizeof(State)) == 0;
}

