    // Rotations: 
    // R: rotate right (around vertical axis) - front->right, right->back, back->left, left->front, top and bottom stay but rotate
    // F: rotate forward (around horizontal axis) - front->bottom, bottom->back, back->top, top->front, left/right stay but rotate
    // U: rotate up (around depth axis) - top->right, right->bottom, bottom->left, left->top, front/back stay but rotate

    // We'll define 3 axes, each with clockwise and counterclockwise = 6 moves
    // Move: axis (0=R,1=F,2=U), dir (0=clockwise,1=counter)

    auto apply_move = [&](const vector<pair<int,int>>& state, int axis, int dir) -> vector<pair<int,int>> {
        vector<pair<int,int>> ns = state;
        int perm[6];
        int rot_add[6] = {0};
        // Initialize identity
        for (int i = 0; i < 6; i++) perm[i] = i;

        if (axis == 0) { // rotate right (around y-axis)
            // cycle: front(0)->right(3), right(3)->back(1), back(1)->left(2), left(2)->front(0)
            // top(4) and bottom(5) rotate
            if (dir == 0) { // clockwise (looking from top)
                perm[0] = 2; // front gets left
                perm[2] = 1; // left gets back
                perm[1] = 3; // back gets right
                perm[3] = 0; // right gets front
                // top and bottom rotate 90 degrees clockwise
                rot_add[4] = 1;
                rot_add[5] = 3; // counterclockwise from bottom perspective = clockwise
            } else { // counterclockwise
                perm[0] = 3;
                perm[3] = 1;
                perm[1] = 2;
                perm[2] = 0;
                rot_add[4] = 3;
                rot_add[5] = 1;
            }
        } else if (axis == 1) { // rotate forward (around x-axis)
            // cycle: front(0)->bottom(5), bottom(5)->back(1), back(1)->top(4), top(4)->front(0)
            if (dir == 0) { // clockwise (looking from right)
                perm[0] = 4; // front gets top
                perm[4] = 1; // top gets back
                perm[1] = 5; // back gets bottom
                perm[5] = 0; // bottom gets front
                rot_add[2] = 1; // left rotates
                rot_add[3] = 3; // right rotates opposite
            } else {
                perm[0] = 5;
                perm[5] = 1;
                perm[1] = 4;
                perm[4] = 0;
                rot_add[2] = 3;
                rot_add[3] = 1;
            }
        } else { // axis == 2, rotate up (around z-axis)
            // cycle: top(4)->right(3), right(3)->bottom(5), bottom(5)->left(2), left(2)->top(4)
            if (dir == 0) { // clockwise (looking from front)
                perm[4] = 2; // top gets left
                perm[2] = 5; // left gets bottom
                perm[5] = 3; // bottom gets right
                perm[3] = 4; // right gets top
                rot_add[0] = 1; // front rotates
                rot_add[1] = 3; // back rotates opposite
            } else {
                perm[4] = 3;
                perm[3] = 5;
                perm[5] = 2;
                perm[2] = 4;
                rot_add[0] = 3;
                rot_add[1] = 1;
            }
        }

        // Build new state
        vector<pair<int,int>> new_state(6);
        for (int i = 0; i < 6; i++) {
            int old_face = state[perm[i]].first;
            int old_rot = state[perm[i]].second;
            int new_rot = (old_rot + rot_add[i]) % 4;
            new_state[i] = {old_face, new_rot};
        }
        return new_state;
    };

    // BFS
    while (!q.empty()) {
        auto cur = q.front(); q.pop();
        uint64_t ch = encode(cur);
        int d = dist[ch];

        for (int axis = 0; axis < 3; axis++) {
            for (int dir = 0; dir < 2; dir++) {
                auto nxt = apply_move(cur, axis, dir);
                uint64_t nh = encode(nxt);
                if (!dist.count(nh)) {
                    dist[nh] = d + 1;
                    q.push(nxt);
                }
            }
        }
    }

    // Now check each state for the condition
    int ans = 1e9;
    for (auto& [state_hash, d] : dist) {
        // Decode state
        vector<pair<int,int>> state(6);
        uint64_t h = state_hash;
        for (int i = 5; i >= 0; i--) {
            int r = h % 4; h /= 4;
            int f = h % 6; h /= 6;
            state[i] = {f, r};
        }

        // Check front (0) and back (1) lower three squares
        // Lower three squares: row index 2 (bottom row) of front and back faces
        bool ok = false;
        for (int face_idx : {0, 1}) {
            auto [orig_face, rot] = state[face_idx];
            // Get the actual grid of that original face
            // Apply rotation: 0=0°, 1=90° clockwise, 2=180°, 3=270° clockwise
            // We need the bottom row (row 2) after rotation
            for (int col = 0; col < 3; col++) {
                int r, c;
                if (rot == 0) { r = 2; c = col; }
                else if (rot == 1) { r = 2 - col; c = 2; }
                else if (rot == 2) { r = 0; c = 2 - col; }
                else { r = col; c = 0; }
                if (cube[orig_face][r][c] == 1) {
                    ok = true;
                    break;
                }
            }
            if (ok) break;
        }
        if (ok) {
            ans = min(ans, d);
        }
    }

    cout << ans << "\n";
    return 0;
}

