#include "cube_solver.cpp"

#include <bits/stdc++.h>
using namespace std;

struct State {
    int U, D, F, B, L, R;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Input format inferred:
    // 6 faces, each as 3 lines of 3 characters.
    // We only need whether each face has at least one hole in its bottom row.
    //
    // Assumption for face order in input:
    // Front, Back, Left, Right, Up, Down
    //
    // A hole is any character not equal to '.'
    // (common choices are 'X', 'O', '#', etc.). If the original judge uses a
    // specific hole character, this still works as long as empty cells are '.'.
    //
    // If your source statement specifies another exact character/order, adapt
    // the parsing accordingly.

    vector<int> hasBottomHole(6, 0);

    for (int face = 0; face < 6; ++face) {
        vector<string> g(3);
        for (int i = 0; i < 3; ++i) {
            if (!(cin >> g[i])) return 0;
        }
        for (int j = 0; j < 3; ++j) {
            if (g[2][j] != '.') hasBottomHole[face] = 1;
        }
    }

    // Face indices in input order:
    // 0=F, 1=B, 2=L, 3=R, 4=U, 5=D
    State start{4, 5, 0, 1, 2, 3};

    auto canPass = [&](const State& s) -> bool {
        return hasBottomHole[s.F] && hasBottomHole[s.B];
    };

    auto rotNorth = [&](const State& s) -> State {
        // Tilt cube so front goes down, up goes front, back goes up, down goes back
        return State{s.F, s.B, s.D, s.U, s.L, s.R};
    };
    auto rotSouth = [&](const State& s) -> State {
        return State{s.B, s.F, s.U, s.D, s.L, s.R};
    };
    auto rotWest = [&](const State& s) -> State {
        // Left goes down, up goes left, right goes up, down goes right
        return State{s.R, s.L, s.F, s.B, s.U, s.D};
    };
    auto rotEast = [&](const State& s) -> State {
        return State{s.L, s.R, s.F, s.B, s.D, s.U};
    };

    queue<State> q;
    map<array<int,6>, int> dist;

    auto key = [&](const State& s) {
        return array<int,6>{s.U, s.D, s.F, s.B, s.L, s.R};
    };

    q.push(start);
    dist[key(start)] = 0;

    while (!q.empty()) {
        State cur = q.front();
        q.pop();
        int d = dist[key(cur)];

        if (canPass(cur)) {
            cout << d << '\n';
            return 0;
        }

        vector<State> nxt = {
            rotNorth(cur), rotSouth(cur), rotWest(cur), rotEast(cur)
        };

        for (auto &ns : nxt) {
            auto k = key(ns);
            if (!dist.count(k)) {
                dist[k] = d + 1;
                q.push(ns);
            }
        }
    }

    // If impossible in all orientations
    cout << -1 << '\n';
    return 0;
}

import sys
from collections import deque

# Faces: U, D, F, B, L, R
# Each face is a 3x3 grid of characters.

def rotate_face_cw(face):
    return [face[6], face[3], face[0],
            face[7], face[4], face[1],
            face[8], face[5], face[2]]

def rot_x(state):
    # Rotate cube around left-right axis so F->U, D->F, B->D, U->B
    U, D, F, B, L, R = state
    return (
        F,          # U
        B,          # D
        D,          # F
        U,          # B
        rotate_face_cw(L),  # side faces spin in place
        rotate_face_cw(R),
    )

def rot_y(state):
    # Rotate cube around up-down axis so L->F, B->L, R->B, F->R
    U, D, F, B, L, R = state
    return (
        rotate_face_cw(U),
        rotate_face_cw(D),
        L,  # F
        R,  # B
        B,  # L
        F,  # R
    )

def rot_z(state):
    # Rotate cube around front-back axis so U->L, R->U, D->R, L->D
    U, D, F, B, L, R = state
    return (
        R,  # U
        L,  # D
        rotate_face_cw(F),
        rotate_face_cw(B),
        U,  # L
        D,  # R
    )

def ok(state):
    U, D, F, B, L, R = state
    # lower three squares of front and back faces: indices 6,7,8
    return any(F[i] == '1' for i in (6, 7, 8)) and any(B[i] == '1' for i in (6, 7, 8))

def encode(state):
    return tuple(tuple(face) for face in state)

def main():
    data = [line.strip() for line in sys.stdin if line.strip()]
    if len(data) < 18:
        return

    faces = []
    idx = 0
    for _ in range(6):
        face = []
        for _ in range(3):
            row = data[idx].replace(" ", "")
            idx += 1
            face.extend(list(row))
        faces.append(face)

    start = tuple(faces)

    q = deque([(start, 0)])
    seen = {encode(start)}

    while q:
        state, dist = q.popleft()
        if ok(state):
            print(dist)
            return

        for nxt in (rot_x(state), rot_y(state), rot_z(state)):
            key = encode(nxt)
            if key not in seen:
                seen.add(key)
